theorem padicValNat_le_padicValNat_pred_factorial_add_one (p : ℕ) (hp : p.Prime) {r s : ℕ}
    (hr : 1 ≤ r) (hs : 1 ≤ s) (hrs : padicValNat p (r !) ≤ padicValNat p (s !)) :
    padicValNat p r ≤ padicValNat p ((s - 1)!) + 1

theorem prime_dvd_isConj_card (p : ℕ) (hp : p.Prime) (g : Equiv.Perm (Fin p)) (hg1 : g ≠ 1)
    (hgp : g.cycleType ≠ {p}) :
    p ∣ Nat.card {h : Equiv.Perm (Fin p) | IsConj g h}

lemma filter_compl_eq_filter_univ_pair {n k : ℕ} {g : Equiv.Perm (Fin n ⊕ Fin k)}
    (hg : g ∈ (HSetPair n k)ᶜ) :
    (HSetPair n k)ᶜ.filter ((orbRelPair n k).r g) = Finset.univ.filter ((orbRelPair n k).r g)

lemma filter_compl_eq_filter_univ {n : ℕ} {g : Equiv.Perm (Fin n ⊕ Fin n)}
    (hg : g ∈ (HSet n)ᶜ) :
    (HSet n)ᶜ.filter ((orbRel n).r g) = Finset.univ.filter ((orbRel n).r g)
